using SimplePZMapmaker.Core;
namespace SimplePZMapmaker.Web.Services;
public sealed class TerrainElevationClient(string directory):IDisposable
{
 private readonly HttpClient http=new(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(25)};
 private readonly SemaphoreSlim admission=new(1,1);
 private const int Zoom=12,Count=1<<Zoom;
 private const double HalfWorld=20037508.342789244;
 public const string Attribution="Terrain Tiles / Tilezen Joerd. USGS SRTM/GMTED2010/3DEP; NOAA ETOPO1; Copernicus EU-DEM (European Union); ArcticDEM (NSF awards1043681/1559691/1542736, DigitalGlobe); Australia Geoscience Australia/Commonwealth2017; Austria offene Daten Österreichs DGM; Canada Open Government Licence; Mexico INEGI2016; New Zealand LINZ/Crown2011; Norway Kartverket; UK Environment Agency2015. Source terms: https://github.com/tilezen/joerd/blob/master/docs/attribution.md";
 public async Task<ElevationSurvey> Fetch(GeoBounds bounds,CancellationToken cancellationToken){
  ProjectValidator.ValidateBounds(bounds);await admission.WaitAsync(cancellationToken);try{using var deadline=CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);deadline.CancelAfter(TimeSpan.FromMinutes(2));var token=deadline.Token;int X(double longitude)=>Math.Clamp((int)Math.Floor((longitude+180)/360*Count),0,Count-1);int Y(double latitude)=>Math.Clamp((int)Math.Floor((1-Math.Asinh(Math.Tan(latitude*Math.PI/180))/Math.PI)/2*Count),0,Count-1);
   var minX=X(bounds.West);var maxX=X(bounds.East);var minY=Y(bounds.North);var maxY=Y(bounds.South);var width=(maxX-minX+1)*256;var height=(maxY-minY+1)*256;if((long)width*height>1_000_000)throw new ArgumentException("DEM требует больше1 миллиона отсчётов; уменьшите область.");var cell=HalfWorld*2/(Count*256);var grid=new ElevationSurvey{CoordinateSystem="EPSG:3857",Columns=width,Rows=height,West=-HalfWorld+minX*256*cell,South=HalfWorld-(maxY+1)*256*cell,CellSize=cell,Source=$"Terrain Tiles (Tilezen/Joerd), AWS Open Data, Terrarium zoom{Zoom}; https://registry.opendata.aws/terrain-tiles/",License=Attribution,Values=new double?[width*height]};Directory.CreateDirectory(directory);
   for(var y=minY;y<=maxY;y++)for(var x=minX;x<=maxX;x++){token.ThrowIfCancellationRequested();var path=Path.Combine(directory,$"{Zoom}-{x}-{y}.png");byte[] tile;var cached=File.Exists(path)&&DateTime.UtcNow-File.GetLastWriteTimeUtc(path)<TimeSpan.FromDays(7)&&new FileInfo(path).Length<=1_000_000;if(cached){tile=await File.ReadAllBytesAsync(path,token);try{TerrariumPng.Decode(tile);}catch(ArgumentException){cached=false;}}else tile=[];
    if(!cached){tile=await Download(x,y,token);TerrariumPng.Decode(tile);var temporary=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{await File.WriteAllBytesAsync(temporary,tile,token);File.Move(temporary,path,true);}finally{if(File.Exists(temporary))File.Delete(temporary);}}
    var values=TerrariumPng.Decode(tile);for(var row=0;row<256;row++)Array.Copy(values,row*256,grid.Values,((y-minY)*256+row)*width+(x-minX)*256,256);
   }ElevationSurvey.Validate(grid);return grid;
  }finally{admission.Release();}
 }
 private async Task<byte[]> Download(int x,int y,CancellationToken token){for(var attempt=0;attempt<2;attempt++){using var request=new HttpRequestMessage(HttpMethod.Get,$"https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{Zoom}/{x}/{y}.png");request.Headers.UserAgent.ParseAdd("SimplePZMapmaker/0.7 (+https://github.com/DinLemon/SimplePZMapmaker)");using var response=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,token);if(!response.IsSuccessStatusCode){if(attempt==0&&(int)response.StatusCode is 429 or >=500){await Task.Delay(500,token);continue;}throw new HttpRequestException($"Поставщик DEM вернул{(int)response.StatusCode}. Исходный мир сохранён; повторите или импортируйте .asc.");}if(response.Content.Headers.ContentLength>1_000_000)throw new ArgumentException("Поставщик вернул слишком большой тайл высот.");using var buffer=new MemoryStream();await using var from=await response.Content.ReadAsStreamAsync(token);var chunk=new byte[16384];int n;while((n=await from.ReadAsync(chunk,token))>0){if(buffer.Length+n>1_000_000)throw new ArgumentException("Тайл высот превышает1МБ.");buffer.Write(chunk,0,n);}return buffer.ToArray();}throw new HttpRequestException("DEM не загружен.");}
 public void Dispose(){http.Dispose();admission.Dispose();}
}
